export type NativeElementProperties<Name extends NativeElementName> =
  NativeElementPropertiesMap[Name];
export type NativeElementEventName<Name extends NativeElementName> =
  keyof NativeElementEventMap[Name];
export type NativeElementEventPayload<
  Name extends NativeElementName,
  Event extends NativeElementEventName<Name>,
> = NativeElementEventMap[Name][Event];
export type NativeElementMethodName<Name extends NativeElementName> =
  keyof NativeElementMethodMap[Name];
export type NativeElementMethodContract<
  Name extends NativeElementName,
  Method extends NativeElementMethodName<Name>,
> = NativeElementMethodMap[Name][Method];
